const src = $json.body ?? $json;
const request = String(src.request ?? '').trim();
if (!request) throw new Error('request is required');

return [{
  json: {
    request_id: `req_${Date.now()}_${Math.random().toString(36).slice(2,8)}`,
    request,
    requested_by: String(src.requested_by ?? 'unknown').trim(),
    context: src.context && typeof src.context === 'object' ? src.context : {},
    received_at: new Date().toISOString()
  }
}];

parameters.text:
=Convert this business request into one proposed action.

Request: {{ $json.request }}
Requested by: {{ $json.requested_by }}
Context: {{ JSON.stringify($json.context) }}

Choose one action_type from: draft_only, internal_summary, send_email, publish_content, update_crm, trigger_workflow, apply_discount, delete_record, financial_change, account_change, other.

Do not claim the action has been executed. Produce a proposal only.

parameters.jsCode:
const request = $('Normalize Request').first().json;
const raw = $json.output && typeof $json.output === 'object' ? $json.output : $json;
const proposal = {
  action_type: String(raw.action_type ?? 'other').toLowerCase(),
  target: String(raw.target ?? 'unspecified'),
  proposed_action: String(raw.proposed_action ?? ''),
  draft_content: String(raw.draft_content ?? ''),
  reasoning: String(raw.reasoning ?? ''),
  confidence: Math.max(0, Math.min(1, Number(raw.confidence ?? 0) || 0)),
  assumptions: Array.isArray(raw.assumptions) ? raw.assumptions : []
};

const high = new Set(['apply_discount','delete_record','financial_change','account_change']);
const medium = new Set(['send_email','publish_content','update_crm','trigger_workflow']);

let risk_level = 'medium';
if (high.has(proposal.action_type)) risk_level = 'high';
else if (['draft_only','internal_summary'].includes(proposal.action_type)) risk_level = 'low';
else if (medium.has(proposal.action_type)) risk_level = 'medium';

return [{
  json: {
    ...request,
    proposal,
    risk_level,
    requires_human_approval: true,
    policy_reason: risk_level === 'high'
      ? 'High-impact or potentially irreversible business action.'
      : risk_level === 'medium'
      ? 'External communication or business-system side effect.'
      : 'Portfolio policy requires review even for low-risk actions.',
    proposal_created_at: new Date().toISOString()
  }
}];

const packet = $('Prepare Approval Packet').first().json;
const body = $json.body ?? $json;
let decision = String(body.decision ?? '').trim().toLowerCase();
if (!['approve','revise','reject'].includes(decision)) decision = 'reject';

return [{
  json: {
    ...packet,
    first_decision: decision,
    first_reviewer: String(body.reviewer ?? 'unknown'),
    first_feedback: String(body.feedback ?? ''),
    first_decision_at: new Date().toISOString()
  }
}];

parameters.text:
=Revise the proposed action using the reviewer's feedback.

Original request: {{ $json.request }}
Previous proposal: {{ JSON.stringify($json.proposal) }}
Reviewer feedback: {{ $json.first_feedback }}

Return a complete replacement proposal. Do not execute anything and do not treat revision as approval.

parameters.jsCode:
const base = $('Normalize Human Decision').first().json;
const raw = $json.output && typeof $json.output === 'object' ? $json.output : $json;
const revised = {
  action_type: String(raw.action_type ?? base.proposal.action_type ?? 'other').toLowerCase(),
  target: String(raw.target ?? base.proposal.target ?? 'unspecified'),
  proposed_action: String(raw.proposed_action ?? ''),
  draft_content: String(raw.draft_content ?? ''),
  reasoning: String(raw.reasoning ?? ''),
  confidence: Math.max(0, Math.min(1, Number(raw.confidence ?? 0) || 0)),
  assumptions: Array.isArray(raw.assumptions) ? raw.assumptions : []
};

const high = new Set(['apply_discount','delete_record','financial_change','account_change']);
const low = new Set(['draft_only','internal_summary']);
const revised_risk_level = high.has(revised.action_type) ? 'high' : low.has(revised.action_type) ? 'low' : 'medium';

return [{
  json: {
    ...base,
    revised_proposal: revised,
    revised_risk_level,
    revision_created_at: new Date().toISOString(),
    approval_status: 'waiting_for_second_human_decision'
  }
}];

const packet = $('Prepare Revised Approval Packet').first().json;
const body = $json.body ?? $json;
let decision = String(body.decision ?? '').trim().toLowerCase();
if (!['approve','reject'].includes(decision)) decision = 'reject';

return [{
  json: {
    ...packet,
    second_decision: decision,
    second_reviewer: String(body.reviewer ?? 'unknown'),
    second_feedback: String(body.feedback ?? ''),
    second_decision_at: new Date().toISOString()
  }
}];

const proposal = $json.revised_proposal ?? $json.proposal;
return [{
  json: {
    ...$json,
    final_status: 'approved',
    execution_status: 'simulated_success',
    executed_action_type: proposal.action_type,
    executed_target: proposal.target,
    executed_payload: proposal,
    executed_at: new Date().toISOString(),
    executor_note: 'Demo executor only. Replace this node with an allow-listed API or sub-workflow in production.'
  }
}];

return [{
  json: {
    ...$json,
    final_status: 'rejected',
    execution_status: 'not_executed',
    executed_at: null,
    executor_note: 'No action was executed because the human decision was reject or invalid.'
  }
}];
